<?php

declare(strict_types=1);

namespace Mrseams\Erdify\Tests\Conformance;

use Mrseams\Erdify\Model\SchemaJson;
use Mrseams\Erdify\Render\Formats;
use Mrseams\Erdify\Render\RenderOptions;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/**
 * Every render fixture in spec/fixtures, generated by upstream erdify, must be
 * reproduced byte for byte. See spec/README.md.
 */
final class RenderConformanceTest extends TestCase
{
    public const SPEC = __DIR__ . '/../../../spec';

    /** @return iterable<string, array{string, string, string, RenderOptions}> */
    public static function renders(): iterable
    {
        foreach (glob(self::SPEC . '/fixtures/*', GLOB_ONLYDIR) ?: [] as $dir) {
            $case = json_decode((string) file_get_contents("$dir/case.json"), true, flags: JSON_THROW_ON_ERROR);
            foreach ($case['variants'] as $variant => $options) {
                $renderOptions = new RenderOptions($options['include_enums'], $options['include_relationships']);
                foreach (Formats::EXTENSIONS as $format => $ext) {
                    $expected = $variant === 'default' && $format === 'json' ? 'model.json' : "$variant$ext";
                    yield basename($dir) . "/$variant$ext" => [$dir, $format, $expected, $renderOptions];
                }
            }
        }
    }

    #[DataProvider('renders')]
    public function testRendersExactlyLikeUpstream(string $dir, string $format, string $expectedFile, RenderOptions $options): void
    {
        $schema = SchemaJson::decode((string) file_get_contents("$dir/model.json"));

        $actual = Formats::renderer($format)->render($schema, $options);

        self::assertSame(file_get_contents("$dir/$expectedFile"), $actual);
    }

    public function testFixturesExist(): void
    {
        self::assertGreaterThanOrEqual(20, count(glob(self::SPEC . '/fixtures/*', GLOB_ONLYDIR) ?: []));
    }
}
